#! /bin/bash

set -e # Exit on error

cd "$(dirname "$0")" # cd to this script dir

OUTPUT="../assets/info-release.json"
MODE="release"
LONG_HASH=$(git rev-parse --verify HEAD)
SHORT_HASH=$(git rev-parse --short HEAD)
DATE=$(date)

if [[ "$1" == "debug" ]]; then
	OUTPUT="../assets/info-debug.json"
	MODE="debug"
	LONG_HASH="${LONG_HASH//?/*}"
	SHORT_HASH="${SHORT_HASH//?/*}"
	DATE="Day DD MMM HH:mm:ss ZNE YYYY"
fi

if [ -z "$(git status --untracked-files=no --porcelain)" ]; then 
	IS_DIRTY=false
else 
	IS_DIRTY=true
fi

function scan_sprite_json() {
	local OUTPUT=$1
	local FILE_JSON=$2
	local FILE_HTML="../assets/${3}.preview.html" # Use preview as submodule might not be fetched
	local THEME_NAME

	SCAN_THEMES=false

	while read -r LINE; do
		#echo $LINE
		if $SCAN_THEMES ; then
			if [[ $LINE == "}" ]]; then
				break
			elif [[ $LINE == *": {" ]]; then
				local THEME_NAME=(${LINE:1:-4}) # Found theme name
				local INFO=$(cat $FILE_HTML | grep "${THEME_NAME}.svg (")
				local VERSION=$(echo $INFO | cut -d "(" -f2 | cut -d ")" -f1)
				local REPO=$(echo $INFO | cut -d "'" -f2 | cut -d "'" -f1)
				local THEME_NAME=$(cat $FILE_JSON | grep "name" | grep -i $THEME_NAME)
				local THEME_NAME=$(echo $THEME_NAME | cut -d "\"" -f4 | cut -d "\"" -f2)
				echo "		{" >> $OUTPUT
				echo "			\"name\": \"${THEME_NAME}\"," >> $OUTPUT
				echo "			\"version\": \"${VERSION}\"," >> $OUTPUT
				echo "			\"url\": \"${REPO}\"" >> $OUTPUT
				echo "		}," >> $OUTPUT
			fi
		else
			if [[ $LINE == "\"themes\": {" ]]; then
				SCAN_THEMES=true
			fi
		fi
	done < "$FILE_JSON"
}

echo "{" > $OUTPUT
echo "	\"__comment\": \"Generated by: $(basename -- "$0")\"," >> $OUTPUT
echo "	\"mode\": \"${MODE}\"," >> $OUTPUT
echo "	\"branch\": \"$(git rev-parse --abbrev-ref HEAD)\"," >> $OUTPUT
echo "	\"commit-hash-full\": \"${LONG_HASH}\"," >> $OUTPUT
echo "	\"commit-hash-short\": \"${SHORT_HASH}\"," >> $OUTPUT
echo "	\"dirty\": ${IS_DIRTY}," >> $OUTPUT
echo "	\"build-date\": \"${DATE}\"," >> $OUTPUT
echo "	\"tag\": \"$(git name-rev --tags --name-only $(git rev-parse HEAD))\"," >> $OUTPUT
echo "	\"dependency-info\": [" >> $OUTPUT
scan_sprite_json $OUTPUT "icons.json" "icons"
scan_sprite_json $OUTPUT "files.json" "files"
truncate -s-2 $OUTPUT
echo >> $OUTPUT
echo "	]" >> $OUTPUT

echo "}" >> $OUTPUT

if [[ $# -eq 0 ]]; then
	./$(basename "$0") debug
fi
